        apply_bit(1'b1, 1'b0); // 11
        apply_bit(1'b0, 1'b0); // 110
        apply_bit(1'b1, 1'b1); // 1101 -> FOUND! start_shifting should be 1

        // Test 4: Verify start_shifting stays high forever (sticky) even with random data
        apply_bit(1'b0, 1'b1);
        apply_bit(1'b0, 1'b1);
        apply_bit(1'b1, 1'b1);
        apply_bit(1'b1, 1'b1);

        // Test 5: Synchronous reset test
        reset = 1;
        @(posedge clk);
        #1;
        if (start_shifting !== 1'b0) begin
            $display("Time %0t: Sync reset error! expected 0, got %b", $time, start_shifting);
            errors = errors + 1;
        end

        // De-reset and check if sequence detection works again
        reset = 0;
        apply_bit(1'b1, 1'b0);
        apply_bit(1'b1, 1'b0);
        apply_bit(1'b0, 1'b0);
        apply_bit(1'b1, 1'b1); // 1101 found again

        #20;

        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
